import json
data = json.load(open('/tmp/opencode/osv_0461.json'))
for v in data.get('vulns', []):
    print(f"ID: {v['id']}  aliases: {v.get('aliases')}")
    print(f"  summary: {v['summary']}")
    for aff in v.get('affected', []):
        pkg = aff.get('package', {})
        for r in aff.get('ranges', []):
            fixed = [e.get('fixed') for e in r.get('events', []) if 'fixed' in e]
            print(f"  {pkg.get('ecosystem')}/{pkg.get('name')} ranges type={r.get('type')} fixed={fixed}")
